/**
 * Matrizes de referência do Saeb alinhadas à BNCC (Inep, 2022), âncora da Matriz Omni.
 * - Matemática (2º, 5º e 9º ano): código do Inep = ano + eixo do conhecimento (N, A, G, M, E) +
 *   eixo cognitivo (1 compreender e aplicar conceitos e procedimentos; 2 resolver problemas e argumentar) + ordem. Ex.: 5N1.2.
 * - Linguagens: Língua Portuguesa (2º, 5º e 9º), Arte e Educação Física (5º e 9º), Língua Inglesa (9º).
 *   O Inep numera as habilidades dentro de cada célula; o código ano + eixo do conhecimento
 *   (S escrita alfabética, L leitura, A análise linguística/semiótica, P produção de textos, R arte,
 *   F educação física, I língua inglesa) + eixo cognitivo (1 reconhecer, 2 analisar, 3 avaliar, 4 produzir) + ordem
 *   é a codificação da Matriz Omni para citar cada célula. Ex.: 5L2.4. No 2º ano não há eixo cognitivo: 2L.3.
 * "OU" em maiúsculas une ações alternativas do mesmo processo; cada item mede uma delas.
 * Transcritas dos documentos públicos do Inep. Fora desses anos e componentes, o parâmetro é a BNCC.
 * (A matriz de 2001, com descritores D1, D2…, saiu na revisão de out/2026.)
 */

export type DescritorSaeb = { codigo: string; topico: string; texto: string };
export type ComponenteSaeb = "Língua Portuguesa" | "Matemática" | "Arte" | "Educação Física" | "Língua Inglesa";
export type MatrizSaeb = { componente: ComponenteSaeb; ano: "2º ano" | "5º ano" | "9º ano"; descritores: DescritorSaeb[] };

